JOB_FEEDBACK_LITERAL_CATALOGS: dict[str, dict[str, str]] = {
    locale: dict(
        zip(JOB_FEEDBACK_LITERAL_TRANSLATION_KEYS, row.split("¦"), strict=True)
    )
    for locale, row in _ROWS.items()
}
